 21→/** Send an email via Resend API */
 22→async function sendViaResend(
 23→  apiKey: string,
 24→  from: { email: string; name: string },
 25→  to: string,
 26→  subject: string,
 27→  htmlContent: string
 28→): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
 29→  const res = await fetch("https://api.resend.com/emails", {
 30→    method: "POST",
 31→    headers: {
 32→      "Authorization": `Bearer ${apiKey}`,
 33→      "Content-Type": "application/json",
 34→    },
 35→    body: JSON.stringify({
 36→      from: `${from.name} <${from.email}>`,
 37→      to: [to],
 38→      subject,
 39→      html: htmlContent,
 40→    }),
 41→  });
 42→
 43→  const body = await res.text();
 44→  let errorMessage: string | undefined;
 45→
 46→  if (!res.ok) {
 47→    try {
 48→      const parsed = JSON.parse(body);
 49→      errorMessage = parsed.message || parsed.error?.message;
 50→    } catch { /* ignore */ }
 51→  }
 52→
 53→  return { ok: res.ok, status: res.status, body, errorMessage };
 54→}
