 56→serve(async (req) => {
 57→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 58→
 59→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 60→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 61→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 62→
 63→  try {
 64→    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
 65→
 66→    if (!to || !template_key) {
 67→      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
 68→        status: 400,
 69→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 70→      });
 71→    }
 72→
 73→    // Load platform config for Resend credentials
 74→    const { data: config, error: configError } = await supabase
 75→      .from("platform_config")
 76→      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
 77→      .limit(1)
 78→      .single();
 79→
 80→    if (configError) throw new Error(`Config error: ${configError.message}`);
 81→
 82→    if (!config?.outbound_email_enabled) {
 83→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
 84→        status: 200,
 85→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 86→      });
 87→    }
 88→
 89→    if (!config.resend_api_key) {
 90→      return new Response(JSON.stringify({ error: "Resend API key not configured" }), {
 91→        status: 400,
 92→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 93→      });
 94→    }
 95→
 96→    // Check per-template notification settings
 97→    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
 98→      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
 99→        status: 200,
100→        headers: { ...corsHeaders, "Content-Type": "application/json" },
101→      });
102→    }
103→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
104→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
105→        status: 200,
106→        headers: { ...corsHeaders, "Content-Type": "application/json" },
107→      });
108→    }
109→
110→    // Load template
111→    const { data: template, error: tplError } = await supabase
112→      .from("email_templates")
113→      .select("subject, body_html")
114→      .eq("template_key", template_key)
115→      .single();
116→
117→    if (tplError || !template) {
118→      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
119→        status: 404,
120→        headers: { ...corsHeaders, "Content-Type": "application/json" },
121→      });
122→    }
123→
124→    // Render template with variables
125→    const subject = renderTemplate(template.subject, variables);
126→    const htmlContent = renderTemplate(template.body_html, variables);
127→
128→    const fromEmail = config.email_from_address || "noreply@rankora.co";
129→    const fromName = config.email_from_name || "Rankora";
130→
131→    // Send via Resend
132→    const result = await sendViaResend(
133→      config.resend_api_key,
134→      { email: fromEmail, name: fromName },
135→      to,
136→      subject,
137→      htmlContent
138→    );
139→
140→    if (!result.ok) {
141→      const friendlyMessage = result.errorMessage || `Resend error (status ${result.status})`;
142→
143→      console.error("Resend error:", result.status, result.body);
144→      await logSystemError({
145→        function_name: "send-email",
146→        error_type: "RESEND_SEND_ERROR",
147→        severity: "warning",
148→        error_message: `Resend error: status=${result.status} body=${result.body}`,
149→      });
150→      return new Response(JSON.stringify({
151→        error: friendlyMessage,
152→      }), {
153→        status: 502,
154→        headers: { ...corsHeaders, "Content-Type": "application/json" },
155→      });
156→    }
157→
158→    return new Response(JSON.stringify({ success: true }), {
159→      status: 200,
160→      headers: { ...corsHeaders, "Content-Type": "application/json" },
161→    });
162→  } catch (err: unknown) {
163→    console.error("send-email error:", err);
164→    await logSystemError({
165→      function_name: "send-email",
166→      error_type: "EMAIL_SEND_ERROR",
167→      severity: "warning",
168→      error_message: errorToMessage(err),
169→      error_stack: errorToStack(err),
170→    });
171→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
172→      status: 500,
173→      headers: { ...corsHeaders, "Content-Type": "application/json" },
174→    });
175→  }
176→});
